const FLAG_EMOJI={USA:"🇺🇸",China:"🇨🇳",Kazakhstan:"🇰🇿","United Kingdom":"🇬🇧",Germany:"🇩🇪",Japan:"🇯🇵",France:"🇫🇷",Russia:"🇷🇺",India:"🇮🇳",Portugal:"🇵🇹",Canada:"🇨🇦",Australia:"🇦🇺",Brazil:"🇧🇷",Italy:"🇮🇹",Spain:"🇪🇸","South Korea":"🇰🇷",Netherlands:"🇳🇱",Sweden:"🇸🇪",Switzerland:"🇨🇭",Norway:"🇳🇴",Mexico:"🇲🇽","Saudi Arabia":"🇸🇦",UAE:"🇦🇪",Turkey:"🇹🇷",Indonesia:"🇮🇩",Singapore:"🇸🇬"};function flagFor(n){return FLAG_EMOJI[n]||"🌐"}document.addEventListener("DOMContentLoaded",()=>{const n=IRWR.groupBy("country"),a=Object.entries(n).sort((n,a)=>a[1].length-n[1].length).slice(0,10),t=Math.max(...a.map(([,n])=>n.length)),o=document.getElementById("countryList"),r=[1,0,2],d=r.map(n=>a[n]).filter(Boolean).map(([n,a],o)=>{const d=r[o]+1,e=Math.round(a.length/t*100);return`\n        <div class="country-row podium rank-${d}" data-country="${IRWR.escapeHtml(n)}">\n          <div class="podium-medal">${d}</div>\n          <div class="podium-flag">${flagFor(n)}</div>\n          <h2 class="podium-name">${IRWR.escapeHtml(n)}</h2>\n          <div class="podium-count num" data-count="${a.length}">0</div>\n          <div class="podium-label">records</div>\n          <div class="country-bar-track"><div class="country-bar" data-pct="${e}"></div></div>\n        </div>\n      `}).join(""),e=a.slice(3).map(([n,a],o)=>{const r=o+4,d=Math.round(a.length/t*100);return`\n        <div class="country-row board" data-country="${IRWR.escapeHtml(n)}">\n          <div class="board-rank">${r}</div>\n          <div class="board-flag">${flagFor(n)}</div>\n          <div class="board-info">\n            <div class="board-top">\n              <span class="board-name">${IRWR.escapeHtml(n)}</span>\n              <span class="board-count num" data-count="${a.length}">0</span>\n            </div>\n            <div class="country-bar-track"><div class="country-bar" data-pct="${d}"></div></div>\n          </div>\n        </div>\n      `}).join("");o.innerHTML=`\n    <div class="country-podium">${d}</div>\n    <div class="country-board">${e}</div>\n  `;const i=new IntersectionObserver(n=>{n.forEach(n=>{n.isIntersecting&&(n.target.style.width=n.target.dataset.pct+"%",i.unobserve(n.target))})},{threshold:.3});document.querySelectorAll(".country-bar").forEach(n=>i.observe(n)),IRWR.initCounters(".country-row .num[data-count]"),IRWR.initTilt(".country-row.podium, .country-row.board")}),IRWR.highlightCountryRow=function(n){document.querySelectorAll(".country-row").forEach(a=>{a.classList.toggle("highlight",a.dataset.country===n)})};